File.WriteAllText("gruss.txt", "Servus aus der Datei!");

string inhalt = File.ReadAllText("gruss.txt");
Console.WriteLine(inhalt);
// Ausgabe: Servus aus der Datei!

var einkauf = new List<string> { "Milch", "Brot", "Käse" };
File.WriteAllLines("einkauf.txt", einkauf);
File.AppendAllText("einkauf.txt", "Äpfel\n");

string[] zeilen = File.ReadAllLines("einkauf.txt");
Console.WriteLine($"{zeilen.Length} Einträge");
foreach (string z in zeilen)
{
    Console.WriteLine("- " + z);
}
// Ausgabe:
// 4 Einträge
// - Milch
// - Brot
// - Käse
// - Äpfel

string pfad = "highscore.txt";
int highscore = 0;

if (File.Exists(pfad))
{
    highscore = int.Parse(File.ReadAllText(pfad));
}
Console.WriteLine("Alter Highscore: " + highscore);

int neuePunkte = 120;
if (neuePunkte > highscore)
{
    File.WriteAllText(pfad, neuePunkte.ToString());
    Console.WriteLine("Neuer Rekord gespeichert!");
}
// Ausgabe beim ersten Start:
// Alter Highscore: 0
// Neuer Rekord gespeichert!

// noten.txt enthält:
// Lena;1
// Ali;3
// Mia;2
int summe = 0;
using (StreamReader reader = new StreamReader("noten.txt"))
{
    string zeile;
    while ((zeile = reader.ReadLine()) != null)
    {
        string[] teile = zeile.Split(';');
        Console.WriteLine($"{teile[0]} hat Note {teile[1]}");
        summe += int.Parse(teile[1]);
    }
}   // hier wird die Datei automatisch geschlossen
Console.WriteLine("Summe: " + summe);
// Ausgabe:
// Lena hat Note 1
// Ali hat Note 3
// Mia hat Note 2
// Summe: 6

using (StreamWriter writer = new StreamWriter("log.txt"))
{
    for (int i = 1; i <= 3; i++)
    {
        writer.WriteLine($"Runde {i} gespielt");
    }
}
Console.WriteLine(File.ReadAllLines("log.txt")[2]);
// Ausgabe: Runde 3 gespielt

