int max = 0;
using (var r = new StreamReader("zahlen.txt"))
{
    string z;
    while ((z = r.ReadLine()) != null)
    {
        int n = int.Parse(z);
        if (n > max) max = n;
    }
}
File.AppendAllText("zahlen.txt", max + "\n");
Console.WriteLine(File.ReadAllLines("zahlen.txt").Length + max);
